async def execute(title=None, body=None, folder=None, tags=None):
    """Create a joplin.note from free text."""
    if not title or not str(title).strip():
        return json.dumps({
            'error': "Missing required argument 'title'",
            'parameter': 'title',
            'expected': 'a non-empty note title',
            'actual': '(empty)',
            'retryable': True,
        })
    vals = {'title': str(title).strip()}
    if body is not None:
        vals['body'] = str(body)
    folder_id = _resolve_folder(folder)
    if folder_id:
        vals['folder_id'] = folder_id
    tag_ids = _resolve_tags(tags)
    if tag_ids:
        vals['tag_ids'] = [(6, 0, tag_ids)]
    note = env['joplin.note'].create(vals)
    return json.dumps({
        'id': note.id,
        'title': note.title,
        'joplin_id': note.joplin_id,
        'folder': note.folder_id.name or None,
        'tags': note.tag_ids.mapped('name'),
    }, ensure_ascii=False, default=str)


def _resolve_folder(name):
    """Return the id of the folder named `name`, creating it on miss.

    Case-insensitive: 'Projekt' and 'projekt' resolve to one folder.
    """
    if not name or not str(name).strip():
        return None
    name = str(name).strip()
    folder = env['joplin.folder'].search(
        [('name', '=ilike', name)], limit=1)
    if not folder:
        folder = env['joplin.folder'].create({'name': name})
    return folder.id


def _resolve_tags(names):
    """Return ids for `names`, creating missing tags. Case-insensitive."""
    if not names:
        return []
    if isinstance(names, str):
        names = [n for n in names.split(',') if n.strip()]
    ids = []
    for raw in names:
        name = str(raw).strip()
        if not name:
            continue
        tag = env['joplin.tag'].search([('name', '=ilike', name)], limit=1)
        if not tag:
            tag = env['joplin.tag'].create({'name': name})
        ids.append(tag.id)
    return ids

async def execute(model=None, res_id=None, title=None, body=None,
                  folder=None, tags=None):
    """Create a joplin.note summarising an Odoo record."""
    if not model or not str(model).strip():
        return json.dumps({
            'error': "Missing required argument 'model'",
            'parameter': 'model',
            'expected': 'an Odoo model technical name',
            'actual': '(empty)',
            'retryable': True,
        })
    model = str(model).strip()
    if res_id is None or str(res_id).strip() == '':
        return json.dumps({
            'error': "Missing required argument 'res_id'",
            'parameter': 'res_id',
            'expected': 'an integer record id',
            'actual': '(empty)',
            'retryable': True,
        })
    try:
        res_id = int(res_id)
    except (TypeError, ValueError):
        return json.dumps({
            'error': "Invalid value for 'res_id'",
            'parameter': 'res_id',
            'expected': 'an integer record id',
            'actual': str(res_id),
            'retryable': True,
        })
    if model not in env.registry:
        return json.dumps({
            'error': 'Unknown model: %s' % model,
            'parameter': 'model',
            'expected': 'an installed Odoo model',
            'actual': model,
            'retryable': False,
        })
    # Reuse the AI core's scoped-model check (odoo-model-tools 2.2) — do
    # not invent a second one. Same function odoo_search/odoo_create use.
    _tools = __import__(
        'odoo.addons.ai_agent_core.core.tools',
        fromlist=['_model_scope_error'])
    scope_err = _tools._model_scope_error(env, model)
    if scope_err:
        return json.dumps({
            'error': scope_err,
            'parameter': 'model',
            'expected': 'a model within the session scope',
            'actual': model,
            'retryable': False,
        })
    record = env[model].browse(res_id).exists()
    if not record:
        return json.dumps({
            'error': '%s #%s not found' % (model, res_id),
            'parameter': 'res_id',
            'expected': 'an existing %s id' % model,
            'actual': str(res_id),
            'retryable': False,
        })
    if not title or not str(title).strip():
        title = '%s %s' % (model, record.display_name)
    if body is None or not str(body).strip():
        body = _default_record_summary(record)
    vals = {'title': str(title).strip(), 'body': str(body)}
    folder_id = _resolve_folder(folder)
    if folder_id:
        vals['folder_id'] = folder_id
    tag_ids = _resolve_tags(tags)
    if tag_ids:
        vals['tag_ids'] = [(6, 0, tag_ids)]
    note = env['joplin.note'].create(vals)
    return json.dumps({
        'id': note.id,
        'title': note.title,
        'joplin_id': note.joplin_id,
        'source': '%s,%s' % (model, res_id),
        'folder': note.folder_id.name or None,
        'tags': note.tag_ids.mapped('name'),
    }, ensure_ascii=False, default=str)


def _default_record_summary(record):
    """A short deterministic summary when the agent supplies no body."""
    lines = ['# %s' % record.display_name]
    for fname in ('name', 'description', 'state'):
        if fname not in record._fields:
            continue
        value = record[fname]
        if not value:
            continue
        lines.append('')
        lines.append('**%s:** %s' % (fname, str(value)[:2000]))
    return '\n'.join(lines)


