async def execute(title=None, body=None, folder=None, tags=None):
    """Create a joplin.note summarising the current conversation."""
    if not title or not str(title).strip():
        return json.dumps({
            'error': "Missing required argument 'title'",
            'parameter': 'title',
            'expected': 'a non-empty note title',
            'actual': '(empty)',
            'retryable': True,
        })
